class Node:
    def __init__(self, value, children=None):
        self.value = value
        self.children = children or []


def flatten(node):
    stack = [node]
    out = []
    while stack:
        curr = stack.pop()
        out.append(curr.value)
        for child in reversed(curr.children):
            stack.append(child)
    return out


def depth(node):
    stack = [(node, 1)]
    max_d = 0
    while stack:
        curr, d = stack.pop()
        if d > max_d:
            max_d = d
        for child in curr.children:
            stack.append((child, d + 1))
    return max_d
```

